<?php require 'config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]);header('Location: admin_orders.php');exit;}$orders=$pdo->query("SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll();$page_title='Manage orders';require 'header.php';?><div class="adminnav"><a href="admin.php">Dashboard</a><a href="admin_products.php">Products & stock</a><a href="admin_orders.php">Orders</a><a href="admin_messages.php">Messages</a><a href="admin_reports.php">Sales reports</a></div><section class="wrap"><h1>Customer orders</h1><table class="table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['email'])?><br><?=e($o['address'])?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Pending','Confirmed','Preparing','Shipped','Out for Delivery','Delivered','Cancelled'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button>Update</button></form></td></tr><?php endforeach;?></table></section><?php require 'footer.php';?>
